WITH unpacked AS (SELECT id, service, host, context, COALESCE(context['region'], 'unknown') AS region_or_default, COALESCE(context['trace'], 'none') AS trace_or_default, SIZE(context) AS num_context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, context['region'] AS region FROM app_logs) SELECT id, service, trace_or_default, num_context, MIN(num_context) OVER (PARTITION BY service, host) AS service_min_num_context, ROW_NUMBER() OVER (PARTITION BY service ORDER BY num_context DESC, id) AS seq_no FROM unpacked;
